import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document } from 'mongoose';

/**
 * MongoDB document for one Pokemon.
 *
 * In Nest + Mongoose this class plays the role an entity plays in other ORMs:
 * it describes one collection. `@Schema()` marks the class so
 * `SchemaFactory` can turn it into a Mongoose schema.
 *
 * Extending `Document` gives each instance the methods and fields Mongoose
 * adds, including `_id` and `toJSON()`. The id is generated by MongoDB on
 * insert. This class does not declare it.
 *
 * The collection name is the pluralized lowercase class name: `pokemons`.
 */
@Schema()
export class Pokemon extends Document {
  /**
   * `@Prop` maps the class field to a MongoDB field.
   *
   * `unique: true` creates a unique index. A second document with the same
   * `name` makes Mongo reject the write with error code 11000.
   * `PokemonService.handleExceptions` turns that code into a 400 response.
   *
   * `index: true` keeps an index on the field so lookups by name stay fast.
   * A unique index already indexes the field; both options are set here so
   * the schema states each intention.
   *
   * Stored names are trimmed and lowercased by the service, which is what
   * makes this unique index treat `"Pikachu"` and `"pikachu"` as one name.
   */
  @Prop({
    unique: true,
    index: true,
  })
  name: string;

  /**
   * Pokedex number. Same index rules as `name`: one document per number,
   * and queries that filter on `no` can use the index.
   */
  @Prop({
    unique: true,
    index: true,
  })
  no: number;
}

/**
 * Runtime schema built from the class decorators above.
 * `PokemonModule` registers this object with Mongoose under `Pokemon.name`.
 * The class is the TypeScript type; this constant is what Mongoose executes.
 */
export const PokemonSchema = SchemaFactory.createForClass(Pokemon);
